} Item;

int cmpFreq(const void* a, const void* b) {
    if (((Item*)b)->freq != ((Item*)a)->freq)
        return ((Item*)b)->freq - ((Item*)a)->freq;
    return ((Item*)a)->val - ((Item*)b)->val; // tiebreak by value ascending
}

int cmpInt(const void* a, const void* b) {
    return *(int*)a - *(int*)b;
}

