        List<Integer> res = new ArrayList<>();
        while (!pq.isEmpty()) {
            Node top = pq.poll(); res.add(top.val);
            if (top.e + 1 < lists.get(top.l).length) pq.offer(new Node(lists.get(top.l)[top.e+1], top.l, top.e+1));
        }
        System.out.println(res);
    }
