                int num = Integer.parseInt(argStrs[i].replace("[", "").replace("]", "").trim());
                small.offer(num);
                large.offer(small.poll());
                if (large.size() > small.size()) small.offer(large.poll());
                res.add(null);
            } else {
                if (small.size() > large.size()) res.add((double)small.peek());
                else res.add((small.peek() + large.peek()) / 2.0);
            }
        }
        System.out.println(res.toString().replace("null", "null"));
    }
}

