import java.util.*;

public class Solution {
    public static void main(String[] cmdArgs) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String opsStr = sc.nextLine().trim();
        if (!sc.hasNextLine()) return;
        String argsStr = sc.nextLine().trim();

        List<String> ops = parseList(opsStr);
        List<List<Integer>> argsList = parseNestedIntList(argsStr);

        PriorityQueue<Integer> pq = new PriorityQueue<>();
        Set<Integer> set = new HashSet<>();
        int curr = 1;
        List<Object> res = new ArrayList<>();

        for (int i = 0; i < ops.size(); i++) {
            String op = ops.get(i).replace("\"", "");
            if (op.equals("SmallestInfiniteSet")) {
                res.add(null);
            } else if (op.equals("popSmallest")) {
                if (!pq.isEmpty()) {
                    int val = pq.poll();
                    set.remove(val);
                    res.add(val);
                } else {
                    res.add(curr++);
                }
            } else if (op.equals("addBack")) {
                int num = argsList.get(i).get(0);
                if (num < curr && set.add(num)) {
                    pq.offer(num);
                }
                res.add(null);
            }
        }
        System.out.println(res.toString().replace("null", "null"));
    }

    private static List<String> parseList(String s) {
        List<String> res = new ArrayList<>();
        s = s.substring(1, s.length() - 1);
        if (s.isEmpty()) return res;
        boolean inQuotes = false;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '"') inQuotes = !inQuotes;
            else if (c == ',' && !inQuotes) {
                res.add(sb.toString().trim().replace("\"", ""));
                sb.setLength(0);
            } else {
                sb.append(c);
            }
        }
        res.add(sb.toString().trim().replace("\"", ""));
        return res;
    }

    private static List<List<Integer>> parseNestedIntList(String s) {
        List<List<Integer>> res = new ArrayList<>();
        s = s.substring(1, s.length() - 1);
        int depth = 0;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '[') {
                depth++;
                if (depth > 1) sb.append(c);
            } else if (c == ']') {
                depth--;
                if (depth > 0) sb.append(c);
                else {
                    List<Integer> sub = new ArrayList<>();
                    String val = sb.toString().trim();
                    if (!val.isEmpty()) {
                        for (String part : val.split(",")) {
                            sub.add(Integer.parseInt(part.trim()));
                        }
                    }
                    res.add(sub);
                    sb.setLength(0);
                }
            } else if (c == ',' && depth == 0) {
                // skip
            } else if (depth > 0) {
                sb.append(c);
            }
        }
        return res;
    }
}
